TLM.f("Sancti/09-02",{"officium":"S. Stephani Hungariæ Regis Confessoris","rule":["vide C5","Gloria"],"fallback":"Commune/C5","from":{"Lectio":"Commune/C5","Graduale":"Commune/C5","GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, Ecclésiæ tuæ, omnípotens Deus: ut beátum Stéphanum Confessórem tuum, quem regnántem in terris propagatórem hábuit, propugnatórem habére mereátur gloriósum in cœlis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 31:8-11"},{"k":"text","la":"Beátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja"},{"k":"ref","la":"Ja 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 19:12-26"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo quidam nóbilis ábiit in regionem longínquam accípere sibi regnum, et reverti. Vocátis autem decem servis suis, dedit eis decem mnas, et ait ad illos: Negotiámini, dum vénio. Cives autem ejus óderant eum: et misérunt legatiónem post illum, dicéntes: Nolumus hunc regnáre super nos. Et factum est, ut redíret accépto regno: et jussit vocári servos, quibus dedit pecúniam, ut sciret, quantum quisque negotiátus esset. Venit autem primus, dicens: Dómine, mna tua decem mnas acquisívit. Et ait illi: Euge, bone serve, quia in módico fuísti fidélis, eris potestátem habens super decem civitátes. Et alter venit, dicens: Dómine, mna tua fecit quinque mnas. Et huic ait: Et tu esto super quinque civitátes. Et alter venit, dicens: Dómine, ecce mna tua, quam hábui repósitam in sudário: tímui enim te, quia homo austérus es: tollis, quod non posuísti, et metis, quod non seminasti. Dicit ei: De ore tuo te júdico, serve nequam. Sciébas, quod ego homo austérus sum, tollens, quod non pósui, et metens, quod non seminávi: et quare non dedísti pecúniam meam ad mensam, ut ego véniens cum usúris útique exegíssem illam? Et astántibus dixit: Auferte ab illo mnam et date illi, qui decem mnas habet. Et dixérunt ei: Dómine, habet decem mnas. Dico autem vobis: Quia omni habénti dabitur, et abundábit: ab eo autem, qui non habet, et, quod habet, auferetur ab eo."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Réspice, quas offérimus, hóstias, omnípotens Deus: et præsta; ut, qui passiónis Dominicæ mystéria celebrámus, imitémur quod ágimus."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut beáti Stephani Confessóris tui fidem cóngrua devotióne sectémur; qui, pro ejúsdem fídei dilatatióne, de terréno regno ad cœléstis regni glóriam méruit perveníre."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu.","kn":"(Ps. 36, 30, 31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne će posrnuti. (Aleluja, Aleluja.) (Ps. 36, 1). Ne zaviđaj sreći ^rješnika i zlotvora! Slava Ocu. Pravednikova.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"55d823fe9085aaab":{"t":"<i>Pomolimo se</i>.\nDaj svojoj Crkvi, molimo, svemogući Bože, da blaženoga Stjepana priznavaoca tvoga zavrijedi imati kao slavnog branitelja na nebu, kao što ga je imala za promicatelja dok je vladao na zemlji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, molimo, svemogući Bože, Crkvi svojoj, da zavrijedi blaženog priznavaoca Tvoga Stjepana imati kao slavnog zagovornika na nebesima, koga je, dok je kraijevao na zemlji, imala kao proširitelja, po G. n.","knRef":"Kniewald 1942, str. 698–699 (snimka 350) (OCR)"},"d0743eab00685bfc":{"t":"Sir 31, 8-11\nČitanje knjige Mudrosti. Blago čovjeku koji se nađe bez ljage i ne teži za zlatom, niti se uzda u novac i blago. Tko je taj, da ga pohvalimo? U svojem je životu učinio divna djela. Tko je u tome prokušan i savršen bit će uvijek slavan. Mogao je sagriješiti, ali nije sagriješio, učiniti zlo, ali nije počinio. Zato priznaje njegova djela Gospodin, a njegovih će se milostinja sjećati sve skupine svetih.","kn":"Čitanje Knjige mudrosti (Crkv. 31, 8-11). Blago čovjeku, koji se našao bez ljage i koji ne ide za zlatom niti se uzda u novac i blago. Tko je taj, da ga hvalimo? Jer je u svom životu učinio divna djela. Vječno će biti slavan, koji je u tom prokušan i savršen; mogao je sagriješiti, a nije sagriješio, i učiniti zlo, a nije učinio. Zato su njegova dobra priznata od Gospodina, i njegove će milostinje kazivati čitav zbor svetih. t!82","knRef":"Kniewald 1942, str. 680–681 (snimka 341) (OCR)"},"929d73ef8c983301":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>.","kn":"(Ps. 91, 13, 14). Pravednik i’aste poput paome i libanonskog cedra u domu Gospodnjem. Ra.no jutrom naviješta Tvoje milosrđe i noću Tvoju vjernost.\n\nAleluja, aleiuja. (Jak. 1, 12) Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, aleluja.","knRef":"Kniewald 1942, str. 786–787 (snimka 394) (OCR)"},"8e24ac5ac11b95c8":{"t":"Lk 19, 12-26\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima ovu usporedbu: Neki čovjek ugledna roda pođe u daleku zemlju da primi kraljevstvo i da se povrati poslije toga. Pozove svojih deset slugu, dade im deset mina i reče im: Trgujte dok se ja ne vratim. Njegovi su ga građani mrzili, pa su za njim poslali vjesnike da mu kažu: Nećemo da ovaj vlada nad nama! Kada je preuzeo kraljevstvo, vrati se, dozove sluge kojima je predao novac, da zna koliko je koji stekao. Dođe prvi i reče: Gospodaru, tvoja mina donijela je deset mina. On mu odgovori: Dobro, slugo, dobri, jer si u malom bio vjeran, ti ćeš vladati nad deset gradova. A dođe i drugi i reče: Gospodaru, tvoja je mina donijela pet mina. I ovom reče: I ti budi nad pet gradova. A dođe i treći, koji reče: Gospodaru, evo tvoje mine, koju sam čuvao u rupcu. Ja sam se tebe bojao, jer si oštar čovjek i uzimaš što nisi ostavio i žanješ što nisi sijao. Odgovori mu: Zli slugo, sudim te po tvojim riječima. Znao si da sam oštar čovjek, da uzimam što nisam ostavio i žanjem što nisam sijao. Zašto nisi moj novac dao u promet, da kada dođem, primim ga s kamatama. I naredi prisutnima: Oduzmite mu minu i dajte onome koji ih ima deset. Oni mu kažu: Gospodaru, on ima deset mina. A ja vam kažem da će se dati onome koji već ima, i on će uživati obilno, a od onoga, koji nema, oduzet će se i ono, što ima.","kn":"t Slijedi sv. evanđelje po Luki (19, 12-26). U ono vrije'me reče Isus svojim učenicima lOvu prispcudobu : Neki plemenit čo-vjek pođe u daleku zemlju, da primi kraljevsko dostojanstvo i da se vrati. I pozove svojih deset slugu, dalde im deset mina i reče: Trgujte, do'k se vratim. A njegovi su ga građani mrzili, te su za njim poslali vjesnike, da mu kažu: Ne ćemo, da ovaj vlada nad nama! Kad je primio kraljevsko dostojanstvo, vrati se i dozove sluge, kojima je bio predao novac, da zna, koliko je 'koji stekao. Dođe prvi i reče: Gospodaru, tvoja je mina donijela deset mina. On mu -odgo'vori: Doibro, slugo dobri! Jer iS'i bio vjeran u maloj stvari, ti ćeš vladati nad deset gradova. A dođe i drugi i reče: Gospodaru, tvoja je mina donijela pet mina. I ovom reče: I ti budi nad pet gradova. A dođe i drugi i reče: Gospodaru, evo tvoje mine, koju sam čuvao u rupcu, jer sam se tebe bojaO', ka'd si oštar čovjek i uzimaš , što nijesi ostavio i žanješ, što nijesl sijao. Odgovori mu: Zli slugo, sudim te po tvojim riječima. Znao si, da sam oštar čovje'k, da uzimam, što nijesam ostavio i žanjem, što nijesam sijao. Zašto nijesi dao moga novca u promet, da kada dođem, primim 'ga s kama tima? I naredi prisutnima: Uzmite minu od njega i dajte je onomu, koji ih ima deset. Oni ;mu'kažu: Gospodaru, on ima 'deset mina. A ja vam kažem, da će se dati onomu, koji već ima i uživat će obilno, a od onoga, koji nema' uzet će se i ono što ima.","knRef":"Kniewald 1942, str. 690–691 (snimka 346) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"968ab9dc8dcf4f7a":{"t":"Pogledaj, svemogući Bože, na darove koje prikazujemo i daj, da mi koji obavljamo tajne muke Gospodnje nasljedujemo što radimo.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"56842ed674d6e163":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim.","kn":"(Mt. 24, 46-47). Blago onomu slugi, koga nađe njegov gospodar budna, kad dođe! zaista vam kažem, da će ga postaviti nad svim imanjem svojim.","knRef":"Kniewald 1942, str. 816–817 (snimka 409) (OCR)"},"432b2f3840a9e1a3":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da prikladnom odanošću nasljedujemo vjeru blaženoga Stjepana priznavaoca tvoga, koji je zavrijedio da zbog širenja iste vjere prispije iz zemaljskog kraljevstva u slavu nebeskog.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Podaj, molimo, svemogući Bože, da prikladnom revnošću nasljedujemo vjeru svetog priznavaoca Tvoga Stjepana, koji je radi širenja iste vjere zaslužio,., da Iz zemaljskog kraljevstva dođe u slavu nebeskog carstva, po G. n.","knRef":"Kniewald 1942, str. 698–699 (snimka 350) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}]}}});
